package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaMsDraft3 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_seeing_first_fruit" to DuaText("Melihat Buah Pertama", "Ya Allah, berkatilah kami dalam buah kami, berkatilah kami di kota kami, dan berkatilah kami dalam sa' dan mudd kami.", "Apabila melihat buah pertama musim ini.", "Doa untuk keberkatan dalam rezeki dan di kota seseorang."),
        "dua_good_news" to DuaText("Atas Berita Yang Menyenangkan", "Segala puji bagi Allah yang dengan nikmat-Nya disempurnakan segala kebaikan.", "Pada menerima berita gembira (dan melakukan sujud syukur).", "Nabi ﷺ berkata demikian apabila melihat sesuatu yang disukainya."),
        "dua_looking_mirror" to DuaText("Melihat di Cermin", "Ya Allah, sebagaimana Engkau telah memperelokkan rupaku, perbaikilah akhlakku juga.", "Apabila melihat cermin.", "Nabi ﷺ membuat doa ini (ia ditetapkan walaupun tanpa menyebut cermin)."),
        "dua_rabbana_taqabbal" to DuaText("Penerimaan Perbuatan", "Ya Tuhan kami, terimalah daripada kami ini; sesungguhnya Engkau Maha Mendengar lagi Maha Mengetahui. Dan terimalah taubat kami; sesungguhnya Engkau Maha Penerima taubat lagi Maha Penyayang.", "Ditanya oleh Ibrahim dan Isma'il (AS) semasa membina Kaabah.", "Doa agar diterima selepas setiap amal kebaikan."),
        "dua_muawwidhat" to DuaText("Tiga Qul (Mu'awwidhat)", "(Surah al-Ikhlas) Katakanlah: Dialah Allah, Yang Maha Esa. Allah yang Maha Kaya. Dia tidak beranak dan tidak pula dilahirkan. Dan tidak ada seorangpun yang setara dengan Dia.\n\n(Surah al-Falaq) Katakanlah: Aku berlindung kepada Tuhan yang menguasai subuh, dari kejahatan makhluk-Nya, dari kejahatan gelap-gelita apabila telah terbenam, dari kejahatan orang-orang yang menghembus pada buhul-buhul, dan dari kejahatan orang yang dengki apabila dia dengki.\n\n(Surah an-Nas) Katakanlah: Aku berlindung kepada Tuhan manusia, Raja manusia, Tuhan manusia, daripada kejahatan pembisik yang berundur, yang membisikkan ke dalam hati manusia, dari kalangan jin dan manusia.", "Tiga surah tiga kali setiap pagi dan petang, dan sebelum tidur, tiup ke tangan dan sapu ke seluruh badan.", "Membacanya tiga kali pagi dan petang sudah memadai untuk segala-galanya."),
        "dua_sabr" to DuaText("Untuk Kesabaran dan Ketabahan", "Ya Tuhan kami, limpahkanlah kesabaran kepada kami, teguhkan pendirian kami dan tolonglah kami terhadap kaum yang kafir.", "Pada masa kesukaran dan konfrontasi.", "Doa tentera Talut."),
        "dua_rabbana_innana_amanna" to DuaText("Pengampunan dan Perlindungan daripada Api", "Ya Tuhan kami, kami telah beriman, maka ampunilah dosa-dosa kami dan peliharalah kami dari siksa neraka.", "Doa Al-Quran.", "Sebuah doa disebutkan antara sifat-sifat orang yang bertakwa."),
        "dua_rabbana_hab_lana_rahmah" to DuaText("Petunjuk dalam Urusan Kita (Ashab al-Kahfi)", "Ya Tuhan kami, berikanlah rahmat kepada kami dari sisi-Mu dan sediakanlah bagi kami petunjuk yang lurus dalam urusan kami.", "Doa Ahli Gua.", "Panduan dalam membuat keputusan dan situasi sukar."),
        "dua_musa_faqir" to DuaText("Dua of Musa (AS) for Provision", "Ya Tuhanku, sesungguhnya aku sangat memerlukan kebaikan yang Engkau turunkan kepadaku.", "Mencari rezeki dan kebaikan — doa Musa (AS) di Madyan.", "Selepas doa ini, Allah menganugerahkan Musa (AS) sebuah rumah, pekerjaan dan seorang isteri."),
        "dua_ayyub" to DuaText("Dua of Ayyub (AS) in Illness", "(Ya Tuhanku) aku telah ditimpa bahaya, dan Engkaulah Yang Maha Penyayang di antara para penyayang.", "Dalam penyakit dan penderitaan.", "Allah menghilangkan penderitaan Ayyub (AS)."),
        "dua_husn_khatimah" to DuaText("Mati sebagai seorang Muslim (Yusuf AS)", "Pencipta langit dan bumi, Engkaulah Pelindungku di dunia dan akhirat. Matikan aku dalam keadaan Islam dan gabungkanlah aku dengan orang-orang yang soleh.", "Doa untuk pengakhiran yang baik.", "Doa Nabi Yusuf (AS)."),
        "dua_shaitan_hamazat" to DuaText("Berlindung daripada Bisikan Syaitan", "Ya Tuhanku, aku berlindung kepada-Mu dari bisikan-bisikan syaitan, dan aku berlindung kepada-Mu ya Tuhanku, daripada mereka mendekatiku.", "Berlindung dari bisikan syaitan.", "Doa Al-Quran untuk mencari perlindungan."),
        "dua_bad_character" to DuaText("Berlindung daripada Perwatakan Buruk", "Ya Allah, aku berlindung kepada-Mu dari akhlak yang buruk, perbuatan yang buruk dan hawa nafsu yang buruk.", "Berlindung dari akhlak, perbuatan dan keinginan yang buruk.", "Doa perlindungan daripada Nabi ﷺ."),
        "dua_zawal_nimah" to DuaText("Berlindung daripada Hilang Berkat", "Ya Allah, aku berlindung kepada-Mu dari hilangnya nikmat-Mu, dari perubahan kesejahteraan yang telah Engkau berikan, dari siksa-Mu yang mendadak dan dari segala kemurkaan-Mu.", "Berlindung daripada kehilangan keberkatan dan dari musibah yang mengejut.", "Doa Nabi ﷺ."),
        "dua_useless_knowledge" to DuaText("Berlindung daripada Ilmu yang Tidak Bermanfaat", "Ya Allah, aku berlindung kepada-Mu dari ilmu yang tidak bermanfaat, dari hati yang tidak takut, dari jiwa yang tidak pernah puas, dan dari doa yang tidak dikabulkan.", "Berlindung dari ilmu yang sia-sia dan hati yang tidak takut kepada Allah.", "Doa perlindungan daripada Nabi ﷺ."),
        "dua_beneficial_knowledge" to DuaText("Ilmu Bermanfaat & Rizq Halal", "Ya Allah, sesungguhnya aku memohon kepada-Mu ilmu yang bermanfaat, rizki yang bersih dan amal yang diterima.", "Selepas solat Subuh.", "Nabi ﷺ berkata demikian selepas salam Subuh."),
        "dua_leprosy_diseases" to DuaText("Perlindungan daripada Penyakit Serius", "Ya Allah, aku berlindung kepada-Mu dari vitiligo, gila, kusta dan segala penyakit yang buruk.", "Perlindungan daripada penyakit serius.", "Doa sunnah untuk memelihara kesihatan."),
        "dua_fear_people" to DuaText("Takut kepada Musuh atau Penindas", "Ya Allah, kami menempatkan Engkau di hadapan mereka dan berlindung kepadaMu dari kejahatan mereka.", "Apabila takut akan kemudaratan sesuatu kaum atau seseorang.", "Nabi ﷺ berkata demikian ketika dia takut kepada suatu kaum."),
        "dua_shirk_protection" to DuaText("Perlindungan daripada Syirik Tersembunyi", "Ya Allah, aku berlindung kepada-Mu dari menyekutukan-Mu dengan sesuatu, dan aku memohon ampun kepada-Mu atas apa yang aku lakukan tanpa aku sadari.", "Untuk menjaga keselamatan dari menunjuk-nunjuk dan syirik yang tersembunyi.", "Syirik yang tersembunyi lebih tersembunyi daripada seekor semut yang merayap."),
        "dua_rain" to DuaText("Bila Hujan", "Ya Allah, turunkanlah hujan yang bermanfaat.", "Bila hujan.", "Hujan adalah waktu di mana do'a diterima."),
        "dua_after_rain" to DuaText("Selepas Hujan", "Kami telah diberi hujan dengan limpah kurnia Allah dan rahmatNya.", "Selepas hujan.", "Orang yang mengatakan ini adalah orang yang beriman kepada Allah."),
        "dua_istisqa" to DuaText("Meminta Hujan (Istisqa)", "Ya Allah turunkanlah hujan kepada kami (tiga kali).", "Apabila tiada hujan.", "Nabi ﷺ berdoa ini dalam khutbah Jumaat dan hujan turun."),
        "dua_heavy_rain" to DuaText("Hujan Terlalu Lebat", "Ya Allah, (biarkan ia jatuh) di sekeliling kami dan bukan pada kami.", "Apabila hujan terlalu lebat.", "Awan bergerak pergi melalui doa Nabi ﷺ."),
        "dua_wind" to DuaText("Apabila Angin Bertiup", "Ya Allah, sesungguhnya aku memohon kepada-Mu kebaikannya, kebaikan yang ada di dalamnya dan kebaikan dari apa yang dikirimkan dengannya, dan aku berlindung kepada-Mu dari kejahatannya, keburukan yang ada di dalamnya dan keburukan apa yang dikirimkannya.", "Apabila angin kencang atau ribut bertiup.", "Nabi ﷺ berdoa ini semasa ribut."),
        "dua_thunder" to DuaText("Mendengar Guruh", "Maha Suci Allah yang guruh bertasbih dengan memuji-Nya, dan para malaikat kerana takut kepada-Nya.", "Apabila mendengar guruh - amalan Abdullah ibn az-Zubayr (RA).", "Dipetik dari Surah ar-Ra'd (13:13)."),
        "dua_new_moon" to DuaText("Melihat Bulan Baru", "Ya Allah, jadikanlah bulan ini terbit atas kami dengan keberkatan, keimanan, keselamatan dan keislaman. (Wahai bulan,) Tuhanku dan Tuhanmu ialah Allah.", "Semasa melihat bulan baru.", "Doa sunnah setiap bulan baru."),
        "dua_janaza_adult" to DuaText("Solat Janaza (Dewasa)", "Ya Allah, ampunilah kami yang hidup dan yang mati, yang hadir dan yang tiada, yang muda dan yang tua, lelaki dan wanita kami. Ya Allah, sesiapa yang Engkau hidupkan di antara kami, hidupkan dia di atas Islam, dan sesiapa di antara kami yang Engkau wafatkan, matikanlah dia dalam keadaan beriman.", "Selepas takbir ketiga solat jenazah.", "Doa sunnah untuk orang dewasa yang telah meninggal dunia."),
        "dua_janaza_child" to DuaText("Solat Janaza (Anak)", "Ya Allah, jadikanlah dia pelopor (dan tuan rumah) bagi kami, jadikanlah dia pahala dan harta bagi kami, dan jadikanlah dia pemberi syafaat bagi kami yang diterima syafaatnya.", "Dalam solat jenazah seorang kanak-kanak (untuk perempuan sebut 'ij'alhā').", "Doa sunnah yang diamalkan oleh Hanafi."),
        "dua_mayyit_awf" to DuaText("Doa Terperinci untuk Almarhum", "Ya Allah, ampunilah dia, rahmatilah dia, berikanlah kesejahteraan dan maafkanlah dia. Jadikanlah penerimaannya mulia dan lapangkan kuburnya, basuhlah dia dengan air, salju dan hujan es, dan bersihkanlah dia dari dosa sebagaimana pakaian putih dibersihkan dari kotoran.", "Dalam solat jenazah atau untuk si mati.", "Awf ibn Malik (RA) berharap bahawa dia adalah orang yang telah meninggal itu."),
        "dua_visiting_graves" to DuaText("Menziarahi Kubur", "Salam sejahtera ke atas kamu, wahai penghuni rumah yang beriman dan Muslim ini. Kami juga, jika Allah menghendaki, akan menyertai kamu. Saya memohon kepada Allah kesejahteraan untuk kami dan untuk anda.", "Apabila memasuki tanah kubur.", "Menziarahi kubur mengingatkan seseorang kepada kematian dan akhirat."),
        "dua_closing_eyes" to DuaText("Apabila Memejamkan Mata Arwah", "Ya Allah, ampunilah (nama), angkatlah darjatnya di kalangan orang-orang yang mendapat petunjuk, jadilah penggantinya di antara orang-orang yang ditinggalkannya. Ampunilah kami dan dia, wahai Tuhan sekalian alam; lapangkan kuburnya dan penuhilah dengan cahaya.", "Ketika menutup mata si mati (menyebut namanya).", "Nabi ﷺ membuat doa ini untuk Abu Salamah (RA)."),
        "dua_condolence" to DuaText("Takziah (Ta'ziyah)", "Sesungguhnya kepunyaan Allah apa yang Dia ambil dan kepunyaan-Nya apa yang Dia berikan, dan segala sesuatu di sisi-Nya ada ajalnya, maka bersabarlah dan harapkan pahala.", "Mengucapkan takziah kepada keluarga selepas kematian.", "Nabi ﷺ menghantar mesej ini kepada anak perempuannya."),
        "dua_placing_in_grave" to DuaText("Menempatkan Almarhum di dalam Kubur", "Dengan nama Allah dan atas jalan Rasulullah ﷺ.", "Ketika menurunkan jenazah ke dalam kubur.", "Doa sunnah pengebumian."),
        "dua_sneezing" to DuaText("Bersin", "Segala puji bagi Allah. — Semoga Allah merahmatimu. — Semoga Allah memberi petunjuk dan memperbaiki urusanmu.", "Semasa bersin; yang mendengar berkata 'Yarhamukallah', lalu yang bersin itu membalas.", "Ia merupakan salah satu hak seorang muslim terhadap muslim yang lain."),
        "dua_toilet_enter" to DuaText("Memasuki Tandas", "Dengan nama Allah. Ya Allah, aku berlindung kepada-Mu dari jin najis lelaki dan perempuan.", "Sebelum melangkah ke tandas dengan kaki kiri.", "Bismillah menjadi tabir antara jin dan manusia."),
        "dua_toilet_exit" to DuaText("Meninggalkan Tandas", "(Ya Allah,) aku memohon ampun kepada-Mu.", "Apabila melangkah keluar dari tandas dengan kaki kanan.", "Nabi ﷺ berkata demikian ketika keluar dari tandas."),
        "dua_thanking" to DuaText("Berterima Kasih kepada Seseorang", "Semoga Allah membalasmu dengan kebaikan.", "Apabila seseorang memberi anda kebaikan.", "Sesiapa yang mengatakan ini telah mengucapkan terima kasih sepenuhnya."),
        "dua_love_for_allah" to DuaText("Apabila Seseorang Kata 'Saya Sayang Kamu kerana Allah'", "Semoga Dia (Allah), yang kerana kamu mencintaiku, mencintaimu.", "Apabila seseorang berkata 'Saya cintakan awak kerana Allah'.", "Sunnah membalas cinta kerana Allah."),
        "dua_seeing_muslim_smile" to DuaText("salam (salam)", "Salam sejahtera ke atas kamu, dan rahmat Allah serta keberkatan-Nya.", "Apabila bertemu seorang muslim.", "Mengucapkan salam penuh mendapat tiga puluh kebaikan."),
        "dua_dressing" to DuaText("Berpakaian", "Segala puji bagi Allah yang memberiku pakaian ini dan memberikannya kepadaku tanpa daya dan kekuatan dariku.", "Apabila berpakaian.", "Berita gembira pengampunan dosa yang lalu."),
    )
}
